  const coin = (x, y, r) => `<circle cx="${x}" cy="${y}" r="${r}" fill="#f2b632"/><circle cx="${x}" cy="${y}" r="${r * .75}" fill="#ffcf3f"/>${shek(x, y + r * .04, r * 1.05, "#b5810f")}`;
