      list.querySelectorAll("." + P + "row").forEach(r => r.onclick = () => {
        const g = G[r.dataset.id]; api.speak(g);
        api.hint(`«${H(api.he(g))}» — ${api.tr(g)} · ${api.g(g.ru)}`);
      });
