      fill(true);
      const sb = document.getElementById("q2Say"); if (sb) sb.hidden = true;
      p.innerHTML = `<div class="q2-wait">Выкладываешь покупки на ленту… 🛒</div>`;
      items.forEach((_, i) => setTimeout(() => { if (api.alive()) snd("pop"); }, 280 * i + 200));
