        () => { const L = left(); L.forEach(tb => tb.classList.add("open")); const it = L[0] && R.items[L[0].dataset.id]; if (it) { api.speak(it); api.hint(`«${api.he(it)}» — ${api.tr(it)}. Скажи это 🎤`); } }
