    el.className = "gm " + cls;
    el.innerHTML = `<div class="gm-top"><span class="gm-title">${title || ""}</span><span class="gm-fire" id="gmFire"></span></div><div class="gm-body"></div><div class="gm-tip" hidden></div>`;
    wrap.appendChild(el);
