      <div class="sh-shelf">${shuffle([...c.products]).map(p => `<button class="sh-box" data-id="${p.id}"><span class="sh-lbl" dir="rtl">${g(p.he)}</span><span class="sh-price">${p.price} ₪</span></button>`).join("")}</div>
